export function generateCommunity(s){if(!s.models.some(m=>m.published)){if(s.week%4===0)addPost(s,'dev','开发者周刊','大家仍在寻找更好用的 AI 工具。真实任务和价格，会决定哪些产品能留下用户。');return;}for(let i=0;i<3;i++){const seg=SEGMENTS[Math.floor(random(s)*SEGMENTS.length)],co=s.cohorts[seg.id],m=s.models.find(x=>x.id===co.model);if(!m)continue;const good=random(s)<co.satisfaction/100;const pool=good?POS[seg.id]:NEG[seg.id];let t=pool[Math.floor(random(s)*pool.length)];if(s.last.capacity<.6&&i===0)t='今天响应有点慢，免费活动人多以后排队明显了。希望先把服务稳住。';else if(s.last.freeDelivery<.7&&i===1)t='宣传的免费额度还没用完就触发了限额，体验有点割裂。';addPost(s,seg.id,AUTHORS[seg.id][Math.floor(random(s)*AUTHORS[seg.id].length)],'试用 '+m.name+'：'+t,good?'positive':'negative',{model:m.id});}}
export function advanceWeek(s){if(s.cash<0)return {error:'现金已不足。可以先洽谈应急融资、签署已有报价，或调整经营方案。'};s.week++;const date=dateOf(s);for(const event of EVENTS){if(date>=event.date&&!s.seenHistory.includes(event.id)){s.seenHistory.push(event.id);s.history.unshift(event);log(s,event.title,event.desc,'history');addPost(s,'everyday','行业快讯',event.title+'。'+event.desc,'neutral',{source:'history',url:event.url});}}
 const running=s.projects.filter(p=>p.status==='running');const requested=sum(running.map(p=>p.gpus));const reserve=s.models.some(m=>m.published)?Math.min(s.gpus*.5,Math.ceil((s.last.requests||0)/22000)):0;const ratio=Math.min(1,(s.gpus-reserve)/Math.max(1,requested));s.usedTrainingGPU=requested*ratio;for(const p of running){if(['integration','collection'].includes(p.type)){p.progress+=ratio/p.weeks;if(p.progress>=.999){p.progress=1;p.status='done';}continue;}if(p.type==='tech'){p.progress+=ratio/p.weeks; if(p.progress>=.999){p.status='done';s.tech[p.tech]=true;log(s,'工程研究完成',p.name+' 已掌握。','success');}continue;}const e=p.estimate;const totalWork=p.pilot?Math.max(1,e.work*.2):e.work;const delta=p.gpus*2.8*ratio/totalWork*(p.config.pace==='careful'?.85:p.config.pace==='aggressive'?1.18:1);p.progress=Math.min(1,p.progress+delta);if(p.fail&&p.progress>=p.failAt){p.progress=Math.min(.94,p.failAt);p.status='failed';p.reason=e.arch==='moe'&&!s.tech.moe?'专家负载失衡，训练出现不稳定。':e.noise>.15?'训练指标异常，抽查发现材料噪声较多。':'训练过程发生数值不稳定，需要检查设置与数据。';log(s,'训练中断 · '+p.config.name,p.reason+(p.config.checkpoint?' 可以检查并从保存进度恢复。':' 未启用检查点，本轮需要重新开始。'),'danger');continue;}if(p.config.checkpoint)p.checkpoint=Math.floor(p.progress*5)/5;p.loss.push(Math.max(.9,p.loss.at(-1)-.12-delta*.8+random(s)*.06));if(p.progress>=.999){p.status='done';createResult(s,p);}}
 for(const f of s.funding.filter(f=>f.status==='pending'&&f.due<=s.week)){const inv=INVESTORS.find(i=>i.id===f.investor),quality=Math.max(...s.models.map(m=>sum(m.scores)/5));const chance=clamp(.62+quality*.002+(f.investor==='growth'?Math.min(.25,totalUsers(s)/20000):s.team.research*.03),.5,.95);if(random(s)<chance){const valuation=300+quality*15+totalUsers(s)*.045+Math.max(0,s.last.revenue)*35;f.amount=inv.amount;f.share=clamp(inv.amount/(valuation+inv.amount),.05,.45);f.status='offered';f.valuation=valuation;log(s,'收到投资报价',inv.name+' 愿投入 ¥'+f.amount+' 万，可在融资页面查看并决定是否接受。','funding');}else{f.status='declined';log(s,'融资反馈',inv.name+' 暂未投资，希望看到更多产品或实验成果。可以之后再次接触。','info');}}
 if(s.week%8===0){const seg=SEGMENTS[Math.floor(random(s)*SEGMENTS.length)];s.trends.push({id:uid(s,'trend'),name:seg.name+' 社区新需求',segment:seg.id,effect:.12+random(s)*.12,until:s.week+6});log(s,'社区风向变化',seg.name+' 的讨论与尝试意愿上升，预计持续 6 周。','trend');}s.trends=s.trends.filter(t=>t.until>=s.week);
 updateMarket(s);for(const m of s.models.filter(m=>m.published&&s.week-m.launched===2)){if(m.claim>12){const penalty=(m.claim-12)*.3;s.reputation=clamp(s.reputation-penalty,0,100);log(s,'发布承诺接受检验',m.name+' 的高调宣传抬高了用户预期，社区开始更严格地审视短板。','info');}}
 generateCommunity(s);if(s.cash<20)log(s,'现金提醒',s.cash<0?'现金已不足，请先解决资金缺口。':'现金低于 ¥20 万，建议检查支出或融资进度。','danger');return {ok:true};}
export function emergencyFunding(s){if(s.cash>=0)return {error:'应急方案仅在现金不足时开放。'};const share=.45;s.cash+=180;s.founder*=1-share;s.holders.forEach(h=>h.share*=1-share);s.holders.push({name:'应急投资',share:45});log(s,'应急融资到账','获得 ¥180 万，投资人获得本轮融资后 45% 股份。','funding');return {ok:true};}
export function validateSave(s){
 if(!s||s.version!==VERSION||typeof s.company!=='string'||s.company.length>100||!Number.isInteger(s.week)||s.week<0||s.week>3000)return false;
 for(const key of ['cash','influence','reputation','reach','gpus','founder','rng','serial','marketing','freeCap'])if(!Number.isFinite(s[key]))return false;
 for(const key of ['models','projects','experiments','benchmarks','posts','logs','history','trends','funding','holders','receipts','ledger','seenHistory','notifications'])if(!Array.isArray(s[key])||s[key].length>10000)return false;
 if(s.customDatasets!==undefined&&(!Array.isArray(s.customDatasets)||!s.customDatasets.every(d=>d&&typeof d.id==='string'&&typeof d.name==='string'&&Number.isFinite(d.tokens)&&d.tokens>0&&Number.isFinite(d.quality)&&Array.isArray(d.weights)&&d.weights.length===5&&d.weights.every(Number.isFinite))))return false;
 if(!s.models.length||!s.cohorts||!s.team||!s.inventory||!s.tech||!s.last||!Number.isFinite(s.last.revenue)||!Number.isFinite(s.last.expense))return false;
 if(s.gpus<1||s.gpus>512||s.founder<0||s.founder>100||s.freeCap<0||s.marketing<0)return false;
 if(!SEGMENTS.every(g=>s.cohorts[g.id]&&['active','paid','potential','satisfaction'].every(k=>Number.isFinite(s.cohorts[g.id][k]))))return false;
 if(!s.models.every(m=>typeof m.id==='string'&&typeof m.name==='string'&&Array.isArray(m.scores)&&m.scores.length===5&&m.scores.every(Number.isFinite)&&Number.isFinite(m.params)&&Number.isFinite(m.activeParams)&&Array.isArray(m.targets)))return false;
 if(!s.projects.every(p=>typeof p.id==='string'&&typeof p.name==='string'&&Number.isFinite(p.progress)&&(p.type==='tech'||(['integration','collection'].includes(p.type)&&p.payload&&Number.isFinite(p.weeks))||(p.config&&p.estimate&&Array.isArray(p.loss)))))return false;
 if(!s.posts.every(p=>typeof p.id==='string'&&typeof p.text==='string'&&typeof p.author==='string'))return false;
 return ROLES.every(r=>Number.isInteger(s.team[r.id])&&s.team[r.id]>=0)&&s.holders.every(h=>Number.isFinite(h.share)&&typeof h.name==='string');
}
